            if (low >= 0xDC00 && low <= 0xDFFF) {
                cp = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
                i++;
            }
        }
        used += mx_utf8_encode(cp, buffer + used);
    }
    return js_str_val(js_new_str(buffer, used));
