    "</style></head><body><main><h1>Mxplorer</h1>"
    "<p>Search or type an address in the bar above.</p></main></body></html>";

/* ====================================================================== */
/* Small helpers                                                          */
/* ====================================================================== */

static void set_status(const char* text) {
    mx_copy(status_message, sizeof(status_message), text);
}

static int text_equal(const char* a, const char* b) {
    return !strcmp(a, b);
}

static int is_settings_page(const browser_tab_t* tab) {
    return text_equal(tab->url, "mos://settings");
}

static int is_home_page(const browser_tab_t* tab) {
    return text_equal(tab->url, "mos://home");
}

static int page_view_height(void) {
    int h = (int)surface_height - TOP - (devtools_open ? mx_devtools_height() : 0);
    return h < 60 ? 60 : h;
}

static void clamp_devtools(void) {
    int max = (int)surface_height - TOP - 80;
    if (mx_devtools_height() > max) mx_devtools_set_height(max);
}

static const char* homepage_url(void) {
    if (homepage_mode == HOMEPAGE_MXPLORER) return "mos://home";
    if (homepage_mode == HOMEPAGE_CUSTOM && custom_homepage[0]) return custom_homepage;
    return "https://google.com";
}

/* ====================================================================== */
/* Settings files                                                         */
/* ====================================================================== */

static int write_file(const char* path, const char* data, size_t length) {
    if (!mos_exists("0:/data") && mos_mkdir("0:/data") != SYS_SUCCESS) return 0;
    /* replace the file so shorter contents leave no stale tail */
    if (mos_exists(path)) mos_syscall(SYS_DELETE, (long)(uintptr_t)path, 0, 0);
    if (mos_create(path, "text", "txt") != SYS_SUCCESS) return 0;
    long fd = mos_open(path, SYS_O_RDWR);
    if (fd < 0) return 0;
    long written = mos_fwrite(fd, data, length);
    long closed = mos_close(fd);
    return written == (long)length && closed == SYS_SUCCESS;
}

static long read_file(const char* path, char* out, size_t capacity) {
    long fd = mos_open(path, SYS_O_RDONLY);
    if (fd < 0) return -1;
    long size = mos_size(fd);
    if (size <= 0 || size >= (long)capacity) {
        mos_close(fd);
        return -1;
    }
    long count = mos_read(fd, out, (size_t)size);
    mos_close(fd);
    if (count < 0) return -1;
    out[count] = '\0';
    return count;
}

static void load_homepage_setting(void) {
    char config[URL_LENGTH + 4];
    long count = read_file(HOMEPAGE_SETTING_PATH, config, sizeof(config));
    if (count < 2 || config[1] != '\n') return;
    if (config[0] == '0') {
        homepage_mode = HOMEPAGE_GOOGLE;
    } else if (config[0] == '1') {
        homepage_mode = HOMEPAGE_MXPLORER;
    } else if (config[0] == '2' && count > 2) {
        size_t end = 2;
        while (end < (size_t)count && config[end] != '\n') end++;
        mx_copy_n(custom_homepage, sizeof(custom_homepage), config + 2, end - 2);
        if (custom_homepage[0]) homepage_mode = HOMEPAGE_CUSTOM;
    }
}

static int save_homepage_setting(void) {
    char config[URL_LENGTH + 4];
    config[0] = (char)('0' + homepage_mode);
    config[1] = '\n';
    config[2] = '\0';
    if (homepage_mode == HOMEPAGE_CUSTOM) {
        mx_append(config, sizeof(config), custom_homepage);
        mx_append(config, sizeof(config), "\n");
    }
    if (!write_file(HOMEPAGE_SETTING_PATH, config, strlen(config))) {
        set_status("Could not save the homepage setting.");
        return 0;
    }
    return 1;
}

static void load_settings(void) {
    char text[512];
    if (read_file(SETTINGS_PATH, text, sizeof(text)) <= 0) return;
    for (char* line = text; *line;) {
        char* end = strchr(line, '\n');
        if (end) *end = '\0';
        char* eq = strchr(line, '=');
        if (eq) {
            *eq = '\0';
            int value = atoi(eq + 1);
            if (!strcmp(line, "theme")) theme_dark = value == 1;
            else if (!strcmp(line, "javascript")) javascript_enabled = value != 0;
            else if (!strcmp(line, "subresources")) subresources_enabled = value != 0;
            else if (!strcmp(line, "darkpages")) dark_pages = value != 0;
            else if (!strcmp(line, "devtools")) mx_devtools_set_height(value);
        }
        if (!end) break;
        line = end + 1;
    }
}

static void save_settings(void) {
    char text[256] = "theme=";
    mx_append_int(text, sizeof(text), theme_dark);
    mx_append(text, sizeof(text), "\njavascript=");
    mx_append_int(text, sizeof(text), javascript_enabled);
    mx_append(text, sizeof(text), "\nsubresources=");
    mx_append_int(text, sizeof(text), subresources_enabled);
    mx_append(text, sizeof(text), "\ndarkpages=");
    mx_append_int(text, sizeof(text), dark_pages);
    mx_append(text, sizeof(text), "\ndevtools=");
    mx_append_int(text, sizeof(text), mx_devtools_height());
    mx_append(text, sizeof(text), "\n");
    if (!write_file(SETTINGS_PATH, text, strlen(text))) set_status("Could not save settings.");
}

static void load_homepage_asset(void) {
    size_t fallback_length = sizeof(home_page_fallback) - 1;
    memcpy(home_page_html, home_page_fallback, fallback_length);
    home_page_html[fallback_length] = '\0';
    home_page_html_length = fallback_length;
    long count = read_file(HOMEPAGE_ASSET_PATH, home_page_html, sizeof(home_page_html));
    if (count > 0) home_page_html_length = (size_t)count;
    else {
        memcpy(home_page_html, home_page_fallback, fallback_length + 1);
        home_page_html_length = fallback_length;
    }
}

/* ====================================================================== */
/* Theme                                                                  */
/* ====================================================================== */

static void read_os_accent(void) {
    uint32_t header[3] = {0, 0, 0};
    long fd = mos_open("0:/programs/mosdesk/settings.dat", SYS_O_RDONLY);
    if (fd <= 0) return;
    long bytes = mos_read(fd, header, sizeof(header));
    mos_close(fd);
    if (bytes == sizeof(header) && header[0] == 0x4D445331u)
        os_accent = 0xFF000000u | (header[2] & 0x00FFFFFFu);
}

static void apply_window_style(void) {
    if (!have_original_style || style_is_dark == theme_dark) return;
    style_is_dark = theme_dark;
    syscall_window_style_t style = original_style;
    if (theme_dark) {
        style.title_bar = theme.frame;
        style.title_text = theme.text;
        style.close_button = theme.frame;
        style.minimize_button = theme.frame;
        style.maximize_button = theme.frame;
        style.close_icon = theme.text;
        style.minimize_icon = theme.text;
        style.maximize_icon = theme.text;
        style.border = theme.border;
        style.content_background = theme.page;
    }
    mos_window_set_style(window_id, style);
}

static int rebuild_theme(void) {
    mx_browser_theme_t previous = theme;
    mx_theme_build(&theme, theme_dark, os_accent);
    return memcmp(&previous, &theme, sizeof(theme)) != 0;
}

/* ====================================================================== */
/* Window                                                                 */
/* ====================================================================== */

static int resize_surface(uint32_t width, uint32_t height) {
    if (width < MIN_WIN_W || height < MIN_WIN_H) return 0;
    uint32_t* fresh = (uint32_t*)malloc((size_t)width * height * sizeof(uint32_t));
    if (!fresh) return 0;
    free(pixels);
    pixels = fresh;
    surface_width = width;
    surface_height = height;
    clamp_devtools();
    return 1;
}

static void update_title(void) {
    browser_tab_t* tab = &tabs[active_tab];
    char title[160];
    mx_copy(title, sizeof(title), tab->title[0] ? tab->title : "New Tab");
    mx_append(title, sizeof(title), " - Mxplorer");
    mos_window_set_title(window_id, title);
}

static mx_ui_state_t ui_state(void);

static void present_chrome_now(void) {
    mx_ui_state_t ui = ui_state();
    mx_ui_draw_chrome(&ui);
}

/* ====================================================================== */
/* Tabs and history                                                       */
/* ====================================================================== */

static void set_tab_title_from_url(browser_tab_t* tab) {
    if (is_settings_page(tab)) {
        mx_copy(tab->title, sizeof(tab->title), "Settings");
        return;
    }
    if (is_home_page(tab)) {
        mx_copy(tab->title, sizeof(tab->title), "New Tab");
        return;
    }
    char local[256];
    if (mx_url_local_path(tab->url, local, sizeof(local))) {
        const char* name = strrchr(local, '/');
        mx_copy(tab->title, sizeof(tab->title), name && name[1] ? name + 1 : local);
        return;
    }
    const char* host = strstr(tab->url, "://");
    host = host ? host + 3 : tab->url;
    size_t length = 0;
    while (host[length] && host[length] != '/' && host[length] != '?' && host[length] != ':')
        length++;
    mx_copy_n(tab->title, sizeof(tab->title), host, length);
    if (!tab->title[0]) mx_copy(tab->title, sizeof(tab->title), "New Tab");
}

static void init_tab(browser_tab_t* tab) {
    memset(tab, 0, sizeof(*tab));
    mx_copy(tab->url, sizeof(tab->url), homepage_url());
    set_tab_title_from_url(tab);
    mx_copy(tab->history[0], sizeof(tab->history[0]), tab->url);
    tab->history_count = 1;
}

static void push_history(browser_tab_t* tab, const char* url) {
    if (tab->history_count > 0 && text_equal(tab->history[tab->history_index], url)) return;
    if (tab->history_index + 1 < tab->history_count) tab->history_count = tab->history_index + 1;
    if (tab->history_count == MAX_HISTORY) {
        memmove(tab->history[0], tab->history[1], sizeof(tab->history[0]) * (MAX_HISTORY - 1));
        tab->history_count--;
        tab->history_index--;
    }
    tab->history_index = tab->history_count++;
    mx_copy(tab->history[tab->history_index], URL_LENGTH, url);
}

static void reset_address(void) {
    mx_copy(address_text, sizeof(address_text), tabs[active_tab].url);
    address_focused = 0;
    address_select_all = 0;
    address_cursor = (int)strlen(address_text);
    address_scroll = 0;
}

/* ====================================================================== */
/* Loading                                                                */
/* ====================================================================== */

static void classify_error(browser_tab_t* tab, const char* error) {
    mx_copy(tab->error_detail, sizeof(tab->error_detail), error);
    if (strstr(error, "Unsafe HTTPS is disabled")) tab->error = MX_PAGE_ERROR_HTTPS_OFF;
    else if (strstr(error, "Network is unavailable")) tab->error = MX_PAGE_ERROR_OFFLINE;
    else if (strstr(error, "larger") || strstr(error, "HTML") || strstr(error, "memory"))
        tab->error = MX_PAGE_ERROR_CONTENT;
    else tab->error = MX_PAGE_ERROR_NETWORK;
}

/* Subresources for pages and scripts (stylesheets, scripts, fetch()). */
static int fetch_resource(void* user, const char* url, const char* kind, char** body,
                          size_t* length) {
    (void)user;
    mx_network_entry_t* entry = mx_network_add(url, kind);
    if (mx_now_ms() - load_started > PAGE_BUDGET_MS && loading) {
        mx_copy(entry->error, sizeof(entry->error), "Skipped: the page took too long to load.");
        resources_skipped++;
        return 0;
    }
    if (loading) {
        char text[160] = "Loading ";
        mx_append(text, sizeof(text), kind);
        mx_append(text, sizeof(text), " ");
        mx_append_int(text, sizeof(text), resources_loaded + 1);
        mx_append(text, sizeof(text), "...");
        set_status(text);
        loading = loading < 90 ? loading + 3 : 90;
        present_chrome_now();
    }
    char local[256];
    if (mx_url_local_path(url, local, sizeof(local))) {
        /* only local pages may read local files */
        char page_local[8];
        long n = mx_url_local_path(tabs[active_tab].url, page_local, sizeof(page_local))
                     ? read_file(local, resource_buffer, MX_HTTP_BODY_MAX) : -1;
        entry->duration_ms = mx_now_ms() - entry->started_ms;
        mx_copy(entry->content_type, sizeof(entry->content_type), "local file");
        if (n < 0) {
            entry->status = 0;
            mx_copy(entry->error, sizeof(entry->error), "The file could not be read.");
            return 0;
        }
        entry->status = 200;
        entry->size = (size_t)n;
        char* copy = (char*)malloc((size_t)n + 1);
        if (!copy) return 0;
        memcpy(copy, resource_buffer, (size_t)n + 1);
        *body = copy;
        *length = (size_t)n;
        resources_loaded++;
        return 1;
    }
    /* pictures and videos may be larger than pages: they get their own buffer */
    int media = !strcmp(kind, "image") || !strcmp(kind, "video");
    size_t capacity = media ? MX_HTTP_MEDIA_MAX : MX_HTTP_BODY_MAX;
    char* buffer = media ? (char*)malloc(capacity) : resource_buffer;
    if (!buffer) {
        mx_copy(entry->error, sizeof(entry->error), "Not enough memory for this file.");
        return 0;
    }
    size_t received = 0;
    char error[128];
    mx_http_info_t info;
    int ok = mx_http_get(url, buffer, capacity, &received, allow_insecure_tls,
                         error, sizeof(error), &info);
    entry->status = info.status;
    entry->duration_ms = mx_now_ms() - entry->started_ms;
    entry->redirects = info.redirects;
    entry->size = received;
    mx_copy(entry->content_type, sizeof(entry->content_type), info.content_type);
    if (!ok || info.status >= 400) {
        mx_copy(entry->error, sizeof(entry->error), ok ? "HTTP error status" : error);
        if (!ok) entry->status = 0;
        char message[200];
        mx_copy(message, sizeof(message), "Failed to load ");
        mx_append(message, sizeof(message), kind);
        mx_append(message, sizeof(message), ": ");
        mx_append(message, sizeof(message), url);
        mx_console_add(MX_LOG_WARN, "Network", 0, message);
        if (media) free(buffer);
        return 0;
    }
    if (media) {
        /* hand over the buffer itself, trimmed to the file */
        char* fitted = (char*)realloc(buffer, received + 1);
        *body = fitted ? fitted : buffer;
        *length = received;
        resources_loaded++;
        return 1;
    }
    char* copy = (char*)malloc(received + 1);
    if (!copy) return 0;
    memcpy(copy, resource_buffer, received);
    copy[received] = '\0';
    *body = copy;
    *length = received;
    resources_loaded++;
    return 1;
}

static void page_navigate_request(const char* url, void* user) {
    (void)user;
    mx_copy(pending_navigation, sizeof(pending_navigation), url);
    pending_navigation_set = 1;
}

static void page_alert(const char* text, void* user) {
    (void)user;
    char message[160] = "Page says: ";
    mx_append(message, sizeof(message), text);
    set_status(message);
    chrome_dirty = 1;
}

static int render_source(const char* source, size_t length, const char* url, int scripts,
                         int dark) {
    mx_html_options_t options;
    memset(&options, 0, sizeof(options));
    options.url = url;
    options.viewport_width = (int)surface_width;
    options.viewport_height = page_view_height();
    options.dark = dark;
    options.scripts = scripts;
    options.subresources = subresources_enabled;
    options.fetch = fetch_resource;
    options.navigate = page_navigate_request;
    options.alert = page_alert;
    mx_html_result_t result = mx_html_load(source, length, &options);
    if (result != MX_HTML_OK) {
        classify_error(&tabs[active_tab], mx_html_error(result));
        tabs[active_tab].error = MX_PAGE_ERROR_CONTENT;
        return 0;
    }
    return 1;
}

/* A page that shows one picture or video, for addresses that are .img or
 * .vid files themselves. */
static char* media_document(const char* url, int kind, size_t* length) {
    char escaped[URL_LENGTH * 6];
    size_t used = 0;
    for (const char* p = url; *p && used + 7 < sizeof(escaped); p++) {
        const char* entity = *p == '&' ? "&amp;" : *p == '"' ? "&quot;" : *p == '<' ? "&lt;"
                           : *p == '>' ? "&gt;" : NULL;
        if (entity) {
            mx_copy(escaped + used, sizeof(escaped) - used, entity);
            used += strlen(entity);
        } else {
            escaped[used++] = *p;
        }
    }
    escaped[used] = '\0';
    const char* name = strrchr(url, '/');
    name = name && name[1] ? name + 1 : url;
    size_t capacity = 1024 + 2 * used + strlen(name) * 6;
    char* page = (char*)malloc(capacity);
    if (!page) return NULL;
    mx_copy(page, capacity, "<!doctype html><html><head><title>");
    for (const char* p = name; *p && *p != '?' && *p != '#'; p++) {
        char one[2] = {*p, 0};
        mx_append(page, capacity, *p == '<' ? "&lt;" : *p == '&' ? "&amp;" : one);
    }
    mx_append(page, capacity, "</title><style>"
        "html,body{margin:0;background:#0e0e0e;color:#ddd}"
        "body{height:100vh;display:flex;align-items:center;justify-content:center}"
        "img,video{display:block;max-width:100%;max-height:100vh}"
        "</style></head><body>");
    mx_append(page, capacity, kind == MX_MEDIA_VIDEO ? "<video controls autoplay src=\"" : "<img src=\"");
    mx_append(page, capacity, escaped);
    mx_append(page, capacity, kind == MX_MEDIA_VIDEO ? "\"></video>" : "\" alt=\"\">");
    mx_append(page, capacity, "</body></html>");
    *length = strlen(page);
    return page;
}

static void load_page(int force_reload) {
    browser_tab_t* tab = &tabs[active_tab];
    page_loaded = 0;
    tab->error = MX_PAGE_ERROR_NONE;
    tab->error_detail[0] = '\0';
    mx_devtools_reset_page();
    mx_html_unload();
    page_dirty = chrome_dirty = 1;
    if (is_settings_page(tab)) {
        set_status("");
        return;
    }
    mx_network_clear();
    resources_loaded = resources_skipped = 0;
    load_started = mx_now_ms();
    if (is_home_page(tab)) {
        page_loaded = render_source(home_page_html, home_page_html_length, "mos://home", 0,
                                    theme_dark);
        tab->scroll_y = 0;
        return;
    }
    char status[160] = "Connecting to ";
    const char* host = strstr(tab->url, "://");
    char local_status[8];
    if (mx_url_local_path(tab->url, local_status, sizeof(local_status)))
        mx_copy(status, sizeof(status), "Opening ");
    mx_append(status, sizeof(status), host ? host + 3 : tab->url);
    set_status(status);
    char message[300] = "Navigated to ";
    mx_append(message, sizeof(message), tab->url);
    mx_console_add(MX_LOG_SYSTEM, "", 0, message);
    loading = 10;
    /* show the loading state before the blocking fetch */
    {
        mx_ui_state_t ui = ui_state();
        mx_ui_draw_chrome(&ui);
        mx_ui_draw_blank(&ui);
        mos_window_present(window_id, pixels, surface_width * 4u, 0, TOP, surface_width,
                           (uint32_t)page_view_height());
    }
    int from_cache = !force_reload && tab->page_source && text_equal(tab->source_url, tab->url);
    int media_kind = mx_media_kind_of_url(tab->url);
    char local_path[256];
    int is_local = mx_url_local_path(tab->url, local_path, sizeof(local_path));
    if (!from_cache && (media_kind || is_local)) {
        /* a picture or video (fetched by the page itself), or a local page */
        char* saved = NULL;
        size_t saved_length = 0;
        if (media_kind) {
            saved = media_document(tab->url, media_kind, &saved_length);
        } else {
            mx_network_entry_t* entry = mx_network_add(tab->url, "document");
            long n = read_file(local_path, page_buffer, MX_HTTP_BODY_MAX);
            mx_copy(entry->content_type, sizeof(entry->content_type), "local file");
            entry->duration_ms = mx_now_ms() - entry->started_ms;
            if (n < 0) {
                const char* why = mos_exists(local_path) == 1
                                      ? "The file could not be read (pages are at most 2 MiB)."
                                      : "There is no file at this address.";
                mx_copy(entry->error, sizeof(entry->error), why);
                classify_error(tab, why);
                tab->error = MX_PAGE_ERROR_CONTENT;
                set_status(why);
                loading = 0;
                return;
            }
            entry->status = 200;
            entry->size = (size_t)n;
            saved = (char*)malloc((size_t)n + 1);
            if (saved) memcpy(saved, page_buffer, (size_t)n + 1);
            saved_length = (size_t)n;
        }
        if (!saved) {
            classify_error(tab, "Not enough memory to keep this page.");
            loading = 0;
            return;
        }
        free(tab->page_source);
        tab->page_source = saved;
        tab->page_source_length = saved_length;
        mx_copy(tab->source_url, sizeof(tab->source_url), tab->url);
        tab->scroll_y = 0;
    } else if (!from_cache) {
        mx_network_entry_t* entry = mx_network_add(tab->url, "document");
        char error[160];
        size_t body_length = 0;
        mx_http_info_t info;
        int ok = mx_http_get(tab->url, page_buffer, MX_HTTP_BODY_MAX, &body_length,
                             allow_insecure_tls, error, sizeof(error), &info);
        entry->status = ok ? info.status : 0;
        entry->duration_ms = mx_now_ms() - entry->started_ms;
        entry->size = body_length;
        entry->redirects = info.redirects;
        mx_copy(entry->content_type, sizeof(entry->content_type), info.content_type);
        if (!ok) {
            mx_copy(entry->error, sizeof(entry->error), error);
            classify_error(tab, error);
            mx_console_add(MX_LOG_ERROR, "Network", 0, error);
            set_status(error);
            loading = 0;
            return;
        }
        if (info.final_url[0] && !text_equal(info.final_url, tab->url)) {
            /* redirects update the address */
            mx_copy(tab->url, sizeof(tab->url), info.final_url);
            mx_copy(tab->history[tab->history_index], URL_LENGTH, info.final_url);
            if (!address_focused) reset_address();
        }
        char* saved = (char*)malloc(body_length + 1);
        if (!saved) {
            classify_error(tab, "Not enough memory to keep this page.");
            loading = 0;
            return;
        }
        memcpy(saved, page_buffer, body_length);
        saved[body_length] = '\0';
        free(tab->page_source);
        tab->page_source = saved;
        tab->page_source_length = body_length;
        mx_copy(tab->source_url, sizeof(tab->source_url), tab->url);
        tab->scroll_y = 0;
        if (info.status >= 400) {
            char text[96] = "Server answered with status ";
            mx_append_int(text, sizeof(text), info.status);
            mx_console_add(MX_LOG_WARN, "Network", 0, text);
        }
    } else {
        mx_network_entry_t* entry = mx_network_add(tab->url, "document");
        entry->status = 200;
        entry->from_cache = 1;
        entry->size = tab->page_source_length;
    }
    loading = 60;
    set_status("Rendering...");
    present_chrome_now();
    page_loaded = render_source(tab->page_source, tab->page_source_length, tab->url,
                                javascript_enabled, theme_dark && dark_pages);
    loading = 0;
    if (page_loaded) {
        const char* title = mx_html_title();
        if (title && *title) mx_copy(tab->title, sizeof(tab->title), title);
        mx_html_set_scroll(tab->scroll_y, (uint32_t)page_view_height());
        const mx_html_stats_t* stats = mx_html_stats();
        char done[160] = "Done in ";
        mx_append_int(done, sizeof(done), mx_now_ms() - load_started);
        mx_append(done, sizeof(done), " ms");
        if (resources_skipped) {
            mx_append(done, sizeof(done), ", skipped ");
            mx_append_int(done, sizeof(done), resources_skipped);
            mx_append(done, sizeof(done), " slow resources");
        }
        set_status(done);
        (void)stats;
    }
    update_title();
}

static void relayout(void) {
    if (!page_loaded) return;
    int scroll = mx_html_scroll_y();
    int dark = is_home_page(&tabs[active_tab]) ? theme_dark : theme_dark && dark_pages;
    mx_html_relayout((int)surface_width, page_view_height(), dark);
    mx_html_set_scroll(scroll, (uint32_t)page_view_height());
    page_dirty = 1;
}

/* ====================================================================== */
/* Navigation                                                             */
/* ====================================================================== */

static int encode_query(char* output, size_t capacity, const char* query) {
    static const char hex[] = "0123456789ABCDEF";
    size_t used = 0;
    for (size_t i = 0; query[i]; i++) {
        unsigned char c = (unsigned char)query[i];
        int safe = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
                   c == '-' || c == '_' || c == '.' || c == '~';
        if (used + (safe ? 1 : 3) >= capacity) return 0;
        if (c == ' ') {
            output[used++] = '+';
        } else if (safe) {
            output[used++] = (char)c;
        } else {
            output[used++] = '%';
            output[used++] = hex[c >> 4];
            output[used++] = hex[c & 15];
        }
    }
    output[used] = '\0';
    return 1;
}

static int normalize_address(const char* input, char* output, size_t capacity, int* is_search) {
    while (*input == ' ') input++;
    size_t length = strlen(input);
    while (length && input[length - 1] == ' ') length--;
    char trimmed[URL_LENGTH];
    mx_copy_n(trimmed, sizeof(trimmed), input, length);
    int has_dot = strchr(trimmed, '.') != NULL;
    int has_colon = strchr(trimmed, ':') != NULL;
    int has_space = strchr(trimmed, ' ') != NULL;
    *is_search = 0;
    if (!length) return 0;
    if (trimmed[0] >= '0' && trimmed[0] <= '9' && trimmed[1] == ':' && trimmed[2] == '/') {
        /* a Minimal-OS path: 0:/users/me/Videos/clip.vid */
        mx_copy(output, capacity, "file:///");
        mx_append(output, capacity, trimmed);
        return strlen(output) < capacity;
    }
    if (mx_starts_with_nocase(trimmed, "file://")) {
        char path[URL_LENGTH];
        if (!mx_url_local_path(trimmed, path, sizeof(path))) return 0;
        mx_copy(output, capacity, "file:///");
        mx_append(output, capacity, path);
        return strlen(output) < capacity;
    }
    if (mx_starts_with_nocase(trimmed, "mos://") || mx_starts_with_nocase(trimmed, "http://") ||
        mx_starts_with_nocase(trimmed, "https://")) {
        if (length >= capacity) return 0;
        mx_copy(output, capacity, trimmed);
        for (size_t i = 0; i < 8 && output[i] && output[i] != ':'; i++) output[i] = mx_lower(output[i]);
        /* "https://example.com" without a path gets one */
        return 1;
    }
    if (has_space || (!has_dot && !has_colon && strcmp(trimmed, "localhost"))) {
        static const char prefix[] = "https://www.google.com/search?q=";
        char encoded[URL_LENGTH];
        if (!encode_query(encoded, sizeof(encoded), trimmed) ||
            sizeof(prefix) - 1 + strlen(encoded) >= capacity)
            return 0;
        mx_copy(output, capacity, prefix);
        mx_append(output, capacity, encoded);
        *is_search = 1;
        return 1;
    }
    mx_copy(output, capacity, "https://");
    mx_append(output, capacity, trimmed);
    return strlen(output) < capacity;
}

static void navigate_to(const char* input) {
    char destination[URL_LENGTH];
    int is_search = 0;
    if (!normalize_address(input, destination, sizeof(destination), &is_search)) {
        set_status("The address is empty or too long.");
        chrome_dirty = 1;
        return;
    }
    browser_tab_t* tab = &tabs[active_tab];
    tab->scroll_y = mx_html_scroll_y();
    homepage_editing = 0;
    mx_copy(tab->url, sizeof(tab->url), destination);
    set_tab_title_from_url(tab);
    if (is_search) mx_copy(tab->title, sizeof(tab->title), "Google Search");
    push_history(tab, destination);
    tab->scroll_y = 0;
    reset_address();
    load_page(0);
    update_title();
}

static void go_history(int delta) {
    browser_tab_t* tab = &tabs[active_tab];
    int index = tab->history_index + delta;
    if (index < 0 || index >= tab->history_count) return;
    tab->scroll_y = mx_html_scroll_y();
    tab->history_index = index;
    mx_copy(tab->url, sizeof(tab->url), tab->history[index]);
    set_tab_title_from_url(tab);
    reset_address();
    load_page(0);
    update_title();
}

static void switch_tab(int index) {
    if (index < 0 || index >= tab_count || index == active_tab) return;
    tabs[active_tab].scroll_y = mx_html_scroll_y();
    active_tab = index;
    reset_address();
    load_page(0);
    update_title();
}

static void new_tab(void) {
    if (tab_count >= MAX_TABS) {
        set_status("You can have up to 12 tabs.");
        chrome_dirty = 1;
        return;
    }
    tabs[active_tab].scroll_y = mx_html_scroll_y();
    init_tab(&tabs[tab_count]);
    active_tab = tab_count++;
    reset_address();
    load_page(0);
    if (!is_home_page(&tabs[active_tab]) && !is_settings_page(&tabs[active_tab])) {
        /* new tabs focus the address bar */
    }
    address_focused = 1;
    address_select_all = 1;
    update_title();
}

static void close_tab(int index) {
    if (index < 0 || index >= tab_count) return;
    free(tabs[index].page_source);
    if (tab_count == 1) {
        init_tab(&tabs[0]);
        active_tab = 0;
    } else {
        for (int i = index + 1; i < tab_count; i++) tabs[i - 1] = tabs[i];
        tab_count--;
        if (active_tab > index) active_tab--;
        else if (active_tab == index && active_tab >= tab_count) active_tab = tab_count - 1;
    }
    drag_tab = -1;
    reset_address();
    load_page(0);
    update_title();
}

static void reorder_tab(int from, int to) {
    if (from < 0 || to < 0 || from >= tab_count || to >= tab_count || from == to) return;
    browser_tab_t moved = tabs[from];
    if (from < to) for (int i = from; i < to; i++) tabs[i] = tabs[i + 1];
    else for (int i = from; i > to; i--) tabs[i] = tabs[i - 1];
    tabs[to] = moved;
    if (active_tab == from) active_tab = to;
    else if (from < active_tab && active_tab <= to) active_tab--;
    else if (to <= active_tab && active_tab < from) active_tab++;
    drag_tab = to;
}

static void reload(void) {
    if (loading) return;
    tabs[active_tab].refresh_count++;
    tabs[active_tab].scroll_y = mx_html_scroll_y();
    load_page(1);
}

/* ====================================================================== */
/* Settings actions                                                       */
/* ====================================================================== */

static void set_theme(int dark) {
    if (theme_dark == dark) return;
    theme_dark = dark;
    rebuild_theme();
    apply_window_style();
    save_settings();
    relayout();
    chrome_dirty = page_dirty = 1;
}

static void toggle_devtools(int open) {
    devtools_open = open;
    if (!open) {
        mx_devtools_blur();
        mx_html_set_highlight(NULL);
    }
    clamp_devtools();
    relayout();
    chrome_dirty = page_dirty = 1;
}

static void begin_custom_homepage(void) {
    homepage_previous_mode = homepage_mode;
    homepage_mode = HOMEPAGE_CUSTOM;
    homepage_editing = 1;
    address_focused = 1;
    mx_copy(address_text, sizeof(address_text), custom_homepage);
    address_cursor = (int)strlen(address_text);
    address_scroll = 0;
    address_select_all = address_cursor != 0;
    set_status("Type the address of your home page, then press Enter.");
}

static void apply_setting(int id) {
    if (id >= MX_SET_CATEGORY && id < MX_SET_CATEGORY + MX_SETTINGS_CATEGORIES) {
        settings_category = id - MX_SET_CATEGORY;
        return;
    }
    switch (id) {
    case MX_SET_HOME_GOOGLE:
    case MX_SET_HOME_MXPLORER:
        homepage_mode = id == MX_SET_HOME_GOOGLE ? HOMEPAGE_GOOGLE : HOMEPAGE_MXPLORER;
        homepage_editing = 0;
        reset_address();
        if (save_homepage_setting())
            set_status(homepage_mode == HOMEPAGE_GOOGLE ? "Home page set to Google."
                                                        : "Home page set to the Mxplorer start page.");
        break;
    case MX_SET_HOME_CUSTOM:
    case MX_SET_HOME_FIELD:
        begin_custom_homepage();
        break;
    case MX_SET_THEME_LIGHT: set_theme(0); break;
    case MX_SET_THEME_DARK: set_theme(1); break;
    case MX_SET_DARK_PAGES:
        dark_pages = !dark_pages;
        save_settings();
        break;
    case MX_SET_JAVASCRIPT:
        javascript_enabled = !javascript_enabled;
        save_settings();
        set_status(javascript_enabled ? "JavaScript is on for new page loads." : "JavaScript is off.");
        break;
    case MX_SET_SUBRESOURCES:
        subresources_enabled = !subresources_enabled;
        save_settings();
        break;
    case MX_SET_UNSAFE_HTTPS:
        allow_insecure_tls = !allow_insecure_tls;
        set_status(allow_insecure_tls ? "Unsafe HTTPS is on for this session. Certificates are not checked."
                                      : "Unsafe HTTPS is off.");
        break;
    case MX_SET_CLEAR_DATA:
        for (int i = 0; i < tab_count; i++) {
            free(tabs[i].page_source);
            tabs[i].page_source = NULL;
            tabs[i].source_url[0] = '\0';
        }
        mx_js_clear_storage();
        mx_network_clear();
        set_status("Cookies, site storage and cached pages were cleared.");
        break;
    case MX_SET_DEVTOOLS:
        toggle_devtools(!devtools_open);
        break;
    }
}

static void save_custom_homepage(void) {
    char normalized[URL_LENGTH];
    int is_search = 0;
    if (!address_text[0] || !normalize_address(address_text, normalized, sizeof(normalized), &is_search) ||
        is_search) {
        set_status("Enter a website address for your home page.");
        return;
    }
    mx_copy(custom_homepage, sizeof(custom_homepage), normalized);
    homepage_mode = HOMEPAGE_CUSTOM;
    homepage_editing = 0;
    reset_address();
    if (save_homepage_setting()) set_status("Home page saved.");
}

/* Window events use SYSCALL_INPUT_MOD_* flags; the kernel's translation
 * expects USB HID modifier bits (LCTRL 0x01, LSHIFT 0x02, RALT 0x40). */
static char key_char(const syscall_window_event_t* event) {
    uint8_t hid = 0;
    if (event->mods & SYSCALL_INPUT_MOD_CTRL) hid |= 0x01;
    if (event->mods & SYSCALL_INPUT_MOD_SHIFT) hid |= 0x02;
    if (event->mods & SYSCALL_INPUT_MOD_ALT) hid |= 0x40;   /* as AltGr, for @ { [ */
    return mos_usb_key_to_ascii((uint8_t)event->key, hid);
}

/* ====================================================================== */
/* Address bar editing                                                    */
/* ====================================================================== */

static void update_address_scroll(void) {
    mx_ui_state_t ui = ui_state();
    int text_x, available;
    mx_ui_omnibox_text_rect(&ui, &text_x, &available);
    if (available < 20) available = 20;
    int length = (int)strlen(address_text);
    if (address_cursor < 0) address_cursor = 0;
    if (address_cursor > length) address_cursor = length;
    if (address_select_all) address_scroll = 0;
    if (address_scroll > address_cursor) address_scroll = address_cursor;
    while (address_scroll < address_cursor &&
           mx_text_width_px(address_text + address_scroll, (size_t)(address_cursor - address_scroll), 14, 0) >
               available)
        address_scroll++;
}

static int address_cursor_at_x(int x) {
    mx_ui_state_t ui = ui_state();
    int text_x, available;
    mx_ui_omnibox_text_rect(&ui, &text_x, &available);
    int length = (int)strlen(address_text);
    int previous = 0;
    for (int i = address_scroll; i < length; i++) {
        int w = mx_text_width_px(address_text + address_scroll, (size_t)(i - address_scroll + 1), 14, 0);
        if (x - text_x < previous + (w - previous) / 2) return i;
        previous = w;
    }
    return length;
}

static void address_key(const syscall_window_event_t* event) {
    int key = (int)event->key;
    if (key == KEY_ENTER) {
        if (homepage_editing) save_custom_homepage();
        else navigate_to(address_text);
        return;
    }
    if (key == KEY_ESCAPE) {
        if (homepage_editing) homepage_mode = homepage_previous_mode;
        homepage_editing = 0;
        reset_address();
        page_dirty = 1;
        return;
    }
    if (key == KEY_BACKSPACE || key == KEY_DELETE) {
        if (address_select_all) {
            address_text[0] = '\0';
            address_cursor = 0;
            address_select_all = 0;
        } else {
            size_t length = strlen(address_text);
            if (key == KEY_BACKSPACE && address_cursor > 0) {
                memmove(address_text + address_cursor - 1, address_text + address_cursor,
                        length - (size_t)address_cursor + 1);
                address_cursor--;
            } else if (key == KEY_DELETE && address_cursor < (int)length) {
                memmove(address_text + address_cursor, address_text + address_cursor + 1,
                        length - (size_t)address_cursor);
            }
        }
        update_address_scroll();
        return;
    }
    if (key == KEY_LEFT || key == KEY_RIGHT || key == KEY_HOME || key == KEY_END) {
        int length = (int)strlen(address_text);
        if (address_select_all) {
            address_cursor = key == KEY_LEFT || key == KEY_HOME ? 0 : length;
            address_select_all = 0;
        } else if (key == KEY_LEFT && address_cursor > 0) address_cursor--;
        else if (key == KEY_RIGHT && address_cursor < length) address_cursor++;
        else if (key == KEY_HOME) address_cursor = 0;
        else if (key == KEY_END) address_cursor = length;
        update_address_scroll();
        return;
    }
    if ((event->mods & SYSCALL_INPUT_MOD_CTRL) && key == KEY_A) {
        address_select_all = 1;
        address_cursor = (int)strlen(address_text);
        address_scroll = 0;
        return;
    }
    char c = key_char(event);
    if (c < 32 || c >= 127) return;
    if (address_select_all) {
        address_text[0] = '\0';
        address_cursor = 0;
        address_scroll = 0;
        address_select_all = 0;
    }
    size_t length = strlen(address_text);
    if (length + 1 < sizeof(address_text)) {
        memmove(address_text + address_cursor + 1, address_text + address_cursor,
                length - (size_t)address_cursor + 1);
        address_text[address_cursor++] = c;
    }
    update_address_scroll();
}

/* ====================================================================== */
/* Input                                                                  */
/* ====================================================================== */

static int devtools_top(void) {
    return (int)surface_height - mx_devtools_height();
}

static void page_scroll_to(int y) {
    mx_html_set_scroll(y, (uint32_t)page_view_height());
    page_dirty = 1;
}

static void handle_hover(int x, int y) {
    mx_ui_state_t ui = ui_state();
    mx_hit_t hit = mx_ui_hit(&ui, x, y);
    int in_devtools = devtools_open && y >= devtools_top();
    if (in_devtools) hit.kind = MX_HIT_NONE;
    if (hit.kind != hover_kind || hit.index != hover_index) {
        int chrome = (hover_kind != MX_HIT_NONE && hover_kind < MX_HIT_PAGE) ||
                     (hit.kind != MX_HIT_NONE && hit.kind < MX_HIT_PAGE);
        int page = hover_kind >= MX_HIT_SETTING || hit.kind >= MX_HIT_SETTING ||
                   hover_kind == MX_HIT_SCROLLBAR || hit.kind == MX_HIT_SCROLLBAR;
        hover_kind = hit.kind;
        hover_index = hit.index;
        if (chrome) chrome_dirty = 1;
        if (page) page_dirty = 1;
    }
    const char* link = NULL;
    if (hit.kind == MX_HIT_PAGE && page_loaded) {
        int doc_y = y - TOP + mx_html_scroll_y();
        if (mx_devtools_picking() && devtools_open) {
            mx_devtools_pick(mx_html_hit(x, doc_y), 0);
            page_dirty = 1;
        } else {
            link = mx_html_link_at(x, doc_y);
        }
    }
    if (strcmp(hover_link, link ? link : "")) {
        mx_copy(hover_link, sizeof(hover_link), link ? link : "");
        page_dirty = 1;
    }
}

static void handle_page_click(int x, int y) {
    if (!page_loaded) return;
    int doc_y = y - TOP + mx_html_scroll_y();
    if (devtools_open && mx_devtools_picking()) {
        mx_devtools_pick(mx_html_hit(x, doc_y), 1);
        page_dirty = 1;
        return;
    }
    char target[URL_LENGTH];
    target[0] = '\0';
    int navigate = mx_html_click(x, doc_y, target, sizeof(target));
    page_dirty = 1;
    if (navigate && target[0]) {
        if (mx_starts_with_nocase(target, "javascript:")) return;
        navigate_to(target);
    }
}

static void handle_mouse(const syscall_window_event_t* event) {
    int x = event->x, y = event->y;
    mouse_x = x;
    mouse_y = y;
    int left_down = (event->buttons & SYSCALL_MOUSE_BTN_LEFT) != 0;
    int pressed = left_down && !(previous_buttons & SYSCALL_MOUSE_BTN_LEFT);
    int released = !left_down && (previous_buttons & SYSCALL_MOUSE_BTN_LEFT);
    previous_buttons = event->buttons;

    if (event->type == SYSCALL_WINDOW_EVENT_MOUSE_WHEEL) {
        if (devtools_open && y >= devtools_top()) {
            if (mx_devtools_wheel(x, y, event->wheel)) page_dirty = 1;
            return;
        }
        if (y < MX_BROWSER_TAB_HEIGHT) {
            tab_scroll += event->wheel < 0 ? 1 : -1;
            mx_ui_state_t ui = ui_state();
            int visible = mx_ui_visible_tabs(&ui);
            if (tab_scroll > tab_count - visible) tab_scroll = tab_count - visible;
            if (tab_scroll < 0) tab_scroll = 0;
            chrome_dirty = 1;
        } else if (y >= TOP && page_loaded && !is_settings_page(&tabs[active_tab])) {
            mx_html_scroll(event->wheel < 0 ? 64 : -64, (uint32_t)page_view_height());
            page_dirty = 1;
            handle_hover(x, y);
        }
        return;
    }

    /* drags in progress */
    if (devtools_open && mx_devtools_resizing()) {
        if (mx_devtools_mouse(x, y, left_down, pressed, released)) {
            if (!left_down) save_settings();
            relayout();
            page_dirty = 1;
        }
        return;
    }
    if (drag_scrollbar >= 0) {
        if (!left_down) {
            drag_scrollbar = -1;
            pressed_kind = MX_HIT_NONE;
            page_dirty = 1;
            return;
        }
        int view = page_view_height();
        int content = mx_html_content_height();
        mx_ui_state_t ui = ui_state();
        int sx, sy, sw, sh;
        if (mx_ui_scrollbar(&ui, &sx, &sy, &sw, &sh)) {
            int track = view - 8 - sh;
            int pos = y - TOP - 4 - drag_scrollbar;
            if (track > 0) page_scroll_to((int)((long)pos * (content - view) / track));
        }
        return;
    }
    if (left_down && drag_tab >= 0 && y < MX_BROWSER_TAB_HEIGHT) {
        mx_ui_state_t ui = ui_state();
        mx_hit_t hit = mx_ui_hit(&ui, x, y);
        if ((hit.kind == MX_HIT_TAB || hit.kind == MX_HIT_TAB_CLOSE) && hit.index != drag_tab) {
            reorder_tab(drag_tab, hit.index);
            chrome_dirty = 1;
        }
        return;
    }
    if (released) {
        drag_tab = -1;
        if (pressed_kind != MX_HIT_NONE) {
            pressed_kind = MX_HIT_NONE;
            chrome_dirty = 1;
        }
    }

    if (devtools_open && y >= devtools_top() && !pressed_kind) {
        if (mx_devtools_mouse(x, y, left_down, pressed, released)) page_dirty = 1;
        if (mx_devtools_take_close_request()) toggle_devtools(0);
        if (pressed) {
            if (address_focused) {
                reset_address();
                chrome_dirty = 1;
            }
            mx_html_blur();
        }
        if (hover_kind != MX_HIT_NONE) {
            hover_kind = MX_HIT_NONE;
            chrome_dirty = 1;
        }
        return;
    }
    if (!pressed) {
        handle_hover(x, y);
        if (devtools_open) mx_devtools_mouse(x, y, left_down, 0, released);
        return;
    }

    mx_ui_state_t ui = ui_state();
    mx_hit_t hit = mx_ui_hit(&ui, x, y);
    pressed_kind = hit.kind;
    if (hit.kind != MX_HIT_OMNIBOX && address_focused && !homepage_editing) {
        reset_address();
        chrome_dirty = 1;
    }
    if (hit.kind != MX_HIT_PAGE) mx_html_blur();
    if (devtools_open) mx_devtools_blur();
    switch (hit.kind) {
    case MX_HIT_TAB:
        drag_tab = hit.index;
        switch_tab(hit.index);
        break;
    case MX_HIT_TAB_CLOSE: close_tab(hit.index); break;
    case MX_HIT_NEW_TAB: new_tab(); break;
    case MX_HIT_BACK: go_history(-1); break;
    case MX_HIT_FORWARD: go_history(1); break;
    case MX_HIT_RELOAD: reload(); break;
    case MX_HIT_HOME: navigate_to(homepage_url()); break;
    case MX_HIT_OMNIBOX:
        if (!address_focused) {
            address_focused = 1;
            address_select_all = 1;
            address_cursor = (int)strlen(address_text);
            address_scroll = 0;
        } else {
            address_select_all = 0;
            address_cursor = address_cursor_at_x(x);
            update_address_scroll();
        }
        break;
    case MX_HIT_THEME: set_theme(!theme_dark); break;
    case MX_HIT_DEVTOOLS: toggle_devtools(!devtools_open); break;
    case MX_HIT_SETTINGS: navigate_to("mos://settings"); break;
    case MX_HIT_SETTING:
        apply_setting(hit.index);
        page_dirty = 1;
        break;
    case MX_HIT_ERROR_ACTION:
        if (hit.index == 0) reload();
        else {
            settings_category = 2;
            navigate_to("mos://settings");
        }
        break;
    case MX_HIT_SCROLLBAR: {
        int sx, sy, sw, sh;
        if (mx_ui_scrollbar(&ui, &sx, &sy, &sw, &sh)) {
            if (y >= sy && y < sy + sh) drag_scrollbar = y - sy;
            else {
                /* page up/down toward the click */
                int view = page_view_height();
                mx_html_scroll(y < sy ? -(view - 40) : view - 40, (uint32_t)view);
                drag_scrollbar = -1;
            }
        }
        page_dirty = 1;
        break;
    }
    case MX_HIT_PAGE:
        handle_page_click(x, y);
        break;
    default:
        break;
    }
    chrome_dirty = 1;
}

static void handle_key(const syscall_window_event_t* event) {
    if (!event->buttons) return;
    int key = (int)event->key;
    int ctrl = (event->mods & SYSCALL_INPUT_MOD_CTRL) != 0;
    int shift = (event->mods & SYSCALL_INPUT_MOD_SHIFT) != 0;
    int alt = (event->mods & SYSCALL_INPUT_MOD_ALT) != 0;
    chrome_dirty = 1;
    /* browser shortcuts */
    if (key == KEY_F12 || (ctrl && shift && key == KEY_I) || (ctrl && key == KEY_Q)) {
        toggle_devtools(!devtools_open);
        return;
    }
    if (ctrl && shift && key == KEY_J) {
        if (!devtools_open) toggle_devtools(1);
        mx_devtools_focus_console();
        page_dirty = 1;
        return;
    }
    if (ctrl && key == KEY_T) { new_tab(); return; }
    if (ctrl && key == KEY_W) { close_tab(active_tab); return; }
    if ((ctrl && key == KEY_R) || key == KEY_F5) { reload(); return; }
    if (ctrl && key == KEY_TAB) {
        switch_tab((active_tab + (shift ? tab_count - 1 : 1)) % tab_count);
        return;
    }
    if (alt && key == KEY_LEFT) { go_history(-1); return; }
    if (alt && key == KEY_RIGHT) { go_history(1); return; }
    if (ctrl && key == KEY_L) {
        mx_html_blur();
        mx_devtools_blur();
        address_focused = 1;
        address_select_all = 1;
        mx_copy(address_text, sizeof(address_text), tabs[active_tab].url);
        address_cursor = (int)strlen(address_text);
        address_scroll = 0;
        return;
    }
    if (devtools_open && mx_devtools_focused()) {
        char c = key_char(event);
        if (mx_devtools_key(key, c, event->mods)) {
            page_dirty = 1;
            return;
        }
    }
    if (address_focused) {
        address_key(event);
        return;
    }
    if (page_loaded && !is_settings_page(&tabs[active_tab])) {
        char c = key_char(event);
        char target[URL_LENGTH];
        target[0] = '\0';
        int focused = mx_html_has_focus();
        int consumed = mx_html_key(key, c, event->mods, target, sizeof(target));
        page_dirty = 1;
        if (consumed == 2 && target[0]) {
            navigate_to(target);
            return;
        }
        if (focused || consumed) return;
        int view = page_view_height();
        switch (key) {
        case KEY_DOWN: mx_html_scroll(48, (uint32_t)view); break;
        case KEY_UP: mx_html_scroll(-48, (uint32_t)view); break;
        case KEY_PAGE_DOWN: mx_html_scroll(view - 48, (uint32_t)view); break;
        case KEY_PAGE_UP: mx_html_scroll(-(view - 48), (uint32_t)view); break;
        case KEY_SPACE: mx_html_scroll(shift ? -(view - 48) : view - 48, (uint32_t)view); break;
        case KEY_HOME: page_scroll_to(0); break;
        case KEY_END: page_scroll_to(1 << 28); break;
        case KEY_BACKSPACE: go_history(-1); break;
        default: break;
        }
    }
}

/* ====================================================================== */
/* Drawing                                                                */
/* ====================================================================== */

static mx_ui_state_t ui_state(void) {
    browser_tab_t* tab = &tabs[active_tab];
    mx_ui_state_t s;
    memset(&s, 0, sizeof(s));
    s.window_id = window_id;
    s.pixels = pixels;
    s.width = surface_width;
    s.height = surface_height;
    s.tabs = tabs;
    s.tab_count = tab_count;
    s.active_tab = active_tab;
    s.tab_scroll = &tab_scroll;
    s.address_focused = address_focused;
    s.address_select_all = address_select_all;
    s.address_cursor = address_cursor;
    s.address_scroll = address_scroll;
    s.address_text = address_text;
    s.loading = loading;
    s.page_loaded = page_loaded;
    s.internal_page = is_settings_page(tab) ? 1 : tab->error ? 2 : 0;
    s.status_message = status_message;
    s.hover_link = hover_link[0] ? hover_link : NULL;
    s.hover_kind = hover_kind;
    s.hover_index = hover_index;
    s.pressed_kind = pressed_kind;
    s.page_height = page_view_height();
    s.content_height = page_loaded ? mx_html_content_height() : 0;
    s.scroll_y = page_loaded ? mx_html_scroll_y() : 0;
    s.settings_category = settings_category;
    s.theme_dark = theme_dark;
    s.dark_pages = dark_pages;
    s.javascript = javascript_enabled;
    s.subresources = subresources_enabled;
    s.allow_insecure_tls = allow_insecure_tls;
    s.homepage_mode = homepage_mode;
    s.homepage_editing = homepage_editing;
    s.custom_homepage = custom_homepage;
    s.devtools_open = devtools_open;
    s.theme = &theme;
    return s;
}

static void draw_page(void) {
    long start = mx_now_ms();
    mx_ui_state_t ui = ui_state();
    browser_tab_t* tab = &tabs[active_tab];
    mx_canvas_t canvas = mx_canvas(pixels, (int)surface_width, (int)surface_height);
    int view = page_view_height();
    if (is_settings_page(tab)) {
        mx_ui_draw_settings(&ui);
    } else if (tab->error) {
        mx_ui_draw_error(&ui);
    } else if (page_loaded) {
        mx_html_draw(&canvas, TOP, view, mx_html_scroll_y());
        mx_ui_draw_page_overlay(&ui);
    } else {
        mx_ui_draw_blank(&ui);
    }
    if (devtools_open) {
        mx_devtools_context_t ctx;
        memset(&ctx, 0, sizeof(ctx));
        ctx.theme = &theme;
        if (is_home_page(tab)) {
            ctx.source = home_page_html;
            ctx.source_length = home_page_html_length;
        } else if (!is_settings_page(tab)) {
            ctx.source = tab->page_source;
            ctx.source_length = tab->page_source_length;
        }
        ctx.url = tab->url;
        ctx.last_frame_ms = last_frame_ms;
        mx_devtools_draw(&canvas, 0, devtools_top(), (int)surface_width, mx_devtools_height(), &ctx);
    }
    mos_window_present(window_id, pixels, surface_width * 4u, 0, TOP, surface_width,
                       surface_height - TOP);
    last_frame_ms = mx_now_ms() - start;
}

/* ====================================================================== */
/* Main                                                                   */
/* ====================================================================== */

int main(int argc, char** argv) {
    if (!mx_text_load_fonts())
        printf("Mxplorer: bundled fonts unavailable; using fallback text\n");
    page_buffer = (char*)malloc(MX_HTTP_BODY_MAX);
    resource_buffer = (char*)malloc(MX_HTTP_BODY_MAX);
    if (!page_buffer || !resource_buffer) {
        printf("Mxplorer: not enough memory for page buffers\n");
        return 1;
    }
    read_os_accent();
    load_settings();
    load_homepage_setting();
    load_homepage_asset();
    rebuild_theme();
    init_tab(&tabs[0]);
    tab_count = 1;
    if (argc > 1 && argv[1] && argv[1][0]) {
        /* run Mxplorer <address or 0:/path/file> */
        char start[URL_LENGTH];
        int is_search = 0;
        if (normalize_address(argv[1], start, sizeof(start), &is_search)) {
            mx_copy(tabs[0].url, sizeof(tabs[0].url), start);
            mx_copy(tabs[0].history[0], URL_LENGTH, start);
            set_tab_title_from_url(&tabs[0]);
        }
    }
    reset_address();

    window_id = mos_window_create(0, 22, 16, WIN_W, WIN_H, "Mxplorer");
    if (!window_id) {
        printf("Mxplorer: unable to create browser window\n");
        return 1;
    }
    mos_window_set_resizable(window_id, true);
    syscall_window_info_t info;
    memset(&info, 0, sizeof(info));
    if (mos_window_get_info(window_id, &info) == SYS_SUCCESS) {
        original_style = info.style;
        have_original_style = 1;
    }
    apply_window_style();
    if (!resize_surface(WIN_W, WIN_H)) {
        printf("Mxplorer: unable to allocate browser surface\n");
        mos_window_close(window_id);
        return 1;
    }
    mx_console_add(MX_LOG_SYSTEM, "", 0, "Mxplorer 0.3 started. Press F12 for developer tools.");
    load_page(0);

    for (;;) {
        syscall_window_event_t event;
        memset(&event, 0, sizeof(event));
        while (mos_window_next_event(window_id, &event) == SYS_SUCCESS) {
            if (event.type == SYSCALL_WINDOW_EVENT_CLOSE_REQUEST) {
                running = 0;
                break;
            }
            if (event.type == SYSCALL_WINDOW_EVENT_RESIZED && event.width > 0 && event.height > 0 &&
                (surface_width != (uint32_t)event.width || surface_height != (uint32_t)event.height)) {
                if (!resize_surface((uint32_t)event.width, (uint32_t)event.height)) continue;
                relayout();
                chrome_dirty = page_dirty = 1;
            } else if (event.type == SYSCALL_WINDOW_EVENT_MOUSE ||
                       event.type == SYSCALL_WINDOW_EVENT_MOUSE_WHEEL) {
                handle_mouse(&event);
            } else if (event.type == SYSCALL_WINDOW_EVENT_KEY) {
                handle_key(&event);
            }
            if (pending_navigation_set) {
                pending_navigation_set = 0;
                navigate_to(pending_navigation);
            }
            memset(&event, 0, sizeof(event));
        }
        if (!running) break;

        syscall_window_info_t now_info;
        if (mos_window_get_info(window_id, &now_info) != SYS_SUCCESS) break;
        if (now_info.width && now_info.height &&
            (surface_width != now_info.width || surface_height != now_info.height)) {
            if (resize_surface(now_info.width, now_info.height)) {
                relayout();
                chrome_dirty = page_dirty = 1;
            }
        }
        long now = mx_now_ms();
        if (page_loaded && mx_html_media_tick(now)) page_dirty = 1;
        if (page_loaded && javascript_enabled) {
            if (mx_html_tick(now)) page_dirty = 1;
            if (pending_navigation_set) {
                pending_navigation_set = 0;
                navigate_to(pending_navigation);
            }
            if (mx_html_update()) page_dirty = 1;
            const char* title = mx_html_title();
            if (title && *title && strcmp(title, tabs[active_tab].title)) {
                mx_copy(tabs[active_tab].title, sizeof(tabs[active_tab].title), title);
                update_title();
                chrome_dirty = 1;
            }
        }
        static unsigned console_seen;
        if (devtools_open && console_seen != mx_console_version()) {
            console_seen = mx_console_version();
            page_dirty = 1;
        }
        if (now - last_theme_check >= 1500) {
            last_theme_check = now;
            uint32_t old = os_accent;
            read_os_accent();
            if (old != os_accent && rebuild_theme()) chrome_dirty = page_dirty = 1;
        }
        if (chrome_dirty) {
            mx_ui_state_t ui = ui_state();
            mx_ui_draw_chrome(&ui);
            chrome_dirty = 0;
        }
        if (page_dirty) {
            draw_page();
            page_dirty = 0;
        }
        mos_sleep(16);
    }

    mx_html_unload();
    free(pixels);
    mos_window_close(window_id);
    return 0;
}

files.media.c:
/* Pictures (.img) and videos (.vid) in pages. See mxplorer/media.h.
 *
 * Pictures are decoded once per address and kept premultiplied, with one
 * scaled copy for the size they were last drawn at. Each <video> element
 * has its own player: its file (in memory, or an open local file), one
 * decoded frame and a clock. Like the Video app, the soundtrack plays in
 * the kernel straight from the file (mos_audio_open_at) and the picture
 * follows the sound's position; a downloaded video's file is written to
 * 0:/data first, since the kernel plays sound from files. */
#include "mxplorer/media.h"
#include "mxplorer/devlog.h"
#include "mxplorer/http.h"
#include "mxplorer/icon_ids.h"
#include "mxplorer/text.h"
#include "mxplorer/util.h"
#include "mosmedia.h"
#include "string.h"
#include "stdlib.h"

#ifdef MX_HOST
#include <stdio.h>
#else
#include "minimalos.h"
#include "audio.h"
#endif

#define MAX_IMAGES 96
#define MAX_PLAYERS 8
#define URL_MAX 1024
#define IMAGE_FILE_MAX (64u * 1024u * 1024u)
#define PIXEL_BUDGET (40u * 1024u * 1024u)   /* decoded pixels kept, all pictures */
#define SOUND_FILE "0:/data/mxplorer-video.vid"
#define BAR_H 36

enum { ST_EMPTY, ST_READY, ST_FAILED };

typedef struct {
    char url[URL_MAX];
    int state;
    int w, h;
    uint32_t* px;        /* premultiplied ARGB */
    uint32_t* scaled;    /* px at sw x sh */
    int sw, sh;
} image_t;

typedef struct {
    mx_node_t* node;
    char url[URL_MAX];
    int state;
    uint8_t* data;        /* downloaded file */
    size_t size;
    long fd;              /* local file, -1 if none */
    char path[256];       /* local file, or SOUND_FILE once written */
    mvid_reader_t r;
    uint32_t* frame;      /* width x height, straight ARGB */
    int64_t shown;
    int playing, ended, started, muted, autoplay_done;
    uint32_t pos_ms;
    long clock_start;
    int sound;            /* the kernel is playing this video's sound */
    uint32_t audio_pos;
    long audio_seen;
    uint32_t last_second;
} player_t;

static image_t images[MAX_IMAGES];
static int image_count;
static size_t pixels_used;
static player_t players[MAX_PLAYERS];
static int player_count;
static mx_fetch_fn fetch_fn;
static void* fetch_user;
static int allow_local;
#ifndef MX_HOST
static char sound_file_url[URL_MAX];   /* whose video is in SOUND_FILE */
#endif
static uint32_t* xmap;
static int xmap_cap;

/* ====================================================================== */
/* Addresses and files                                                    */
/* ====================================================================== */

int mx_media_kind_of_url(const char* url) {
    if (!url) return MX_MEDIA_NONE;
    size_t n = 0;
    while (url[n] && url[n] != '?' && url[n] != '#') n++;
    if (n < 5 || url[n - 4] != '.') return MX_MEDIA_NONE;
    char ext[4] = {mx_lower(url[n - 3]), mx_lower(url[n - 2]), mx_lower(url[n - 1]), 0};
    if (!strcmp(ext, "img")) return MX_MEDIA_IMAGE;
    if (!strcmp(ext, "vid")) return MX_MEDIA_VIDEO;
    return MX_MEDIA_NONE;
}

#ifdef MX_HOST
/* On the build PC "0:/x" is the host's "/x". */
static const char* host_path(const char* path) {
    return path[0] >= '0' && path[0] <= '9' && path[1] == ':' ? path + 2 : path;
}
#endif

static uint8_t* read_local(const char* path, size_t limit, size_t* size) {
#ifdef MX_HOST
    FILE* f = fopen(host_path(path), "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t* d = n > 0 && (size_t)n <= limit ? (uint8_t*)malloc((size_t)n) : NULL;
    if (d && fread(d, 1, (size_t)n, f) != (size_t)n) { free(d); d = NULL; }
    fclose(f);
    if (d) *size = (size_t)n;
    return d;
#else
    long fd = mos_open(path, SYS_O_RDONLY);
    if (fd < 0) return NULL;
    long n = mos_size(fd);
    uint8_t* d = n > 0 && (size_t)n <= limit ? (uint8_t*)malloc((size_t)n) : NULL;
    size_t got = 0;
    while (d && got < (size_t)n) {
        long r = mos_read(fd, d + got, (size_t)n - got);
        if (r <= 0) { free(d); d = NULL; break; }
        got += (size_t)r;
    }
    mos_close(fd);
    if (d) *size = (size_t)n;
    return d;
#endif
}

/* The whole file at `url`; NULL when it cannot be had. */
static uint8_t* load_file(const char* url, const char* kind, size_t limit, size_t* size) {
    char path[256];
    if (mx_url_local_path(url, path, sizeof(path))) {
        if (!allow_local) {
            mx_console_add(MX_LOG_WARN, "Media", 0,
                           "Pages from the network cannot show local files.");
            return NULL;
        }
        uint8_t* d = read_local(path, limit, size);
        mx_network_entry_t* e = mx_network_add(url, kind);
        e->status = d ? 200 : 0;
        e->size = d ? *size : 0;
        mx_copy(e->content_type, sizeof(e->content_type), "local file");
        if (!d) mx_copy(e->error, sizeof(e->error), "The file could not be read.");
        return d;
    }
    if (!fetch_fn) return NULL;
    char* body = NULL;
    size_t length = 0;
    if (!fetch_fn(fetch_user, url, kind, &body, &length) || !body) return NULL;
    *size = length;
    return (uint8_t*)body;
}

static void report(const char* what, const char* url) {
    char text[300];
    mx_copy(text, sizeof(text), what);
    mx_append(text, sizeof(text), ": ");
    mx_append(text, sizeof(text), url);
    mx_console_add(MX_LOG_WARN, "Media", 0, text);
}

/* ====================================================================== */
/* Pictures                                                               */
/* ====================================================================== */

static uint32_t premultiply(uint32_t c) {
    uint32_t a = c >> 24;
    if (a == 255) return c;
    if (a == 0) return 0;
    uint32_t r = ((c >> 16) & 255u) * a / 255u, g = ((c >> 8) & 255u) * a / 255u,
             b = (c & 255u) * a / 255u;
    return a << 24 | r << 16 | g << 8 | b;
}

static image_t* find_image(const char* url) {
    for (int i = 0; i < image_count; i++)
        if (!strcmp(images[i].url, url)) return &images[i];
    return NULL;
}

static image_t* get_image(const char* url) {
    image_t* img = find_image(url);
    if (img) return img;
    if (image_count >= MAX_IMAGES) return NULL;
    img = &images[image_count++];
    memset(img, 0, sizeof(*img));
    mx_copy(img->url, sizeof(img->url), url);
    img->state = ST_FAILED;
    size_t size = 0;
    uint8_t* data = load_file(url, "image", IMAGE_FILE_MAX, &size);
    if (!data) {
        report("Could not load the picture", url);
        return img;
    }
    mimg_info_t info;
    if (!mimg_info(data, size, &info)) {
        report("Not a .img picture, or damaged", url);
        free(data);
        return img;
    }
    size_t count = (size_t)info.width * info.height;
    if (pixels_used + count > PIXEL_BUDGET) {
        report("Too many pictures on this page; skipped", url);
        free(data);
        return img;
    }
    img->px = (uint32_t*)malloc(count * 4u);
    if (!img->px || !mimg_decode(data, size, img->px, info.width)) {
        report(img->px ? "Damaged .img picture" : "Not enough memory for the picture", url);
        free(img->px);
        img->px = NULL;
        free(data);
        return img;
    }
    free(data);
    if (info.alpha)
        for (size_t i = 0; i < count; i++) img->px[i] = premultiply(img->px[i]);
    img->w = (int)info.width;
    img->h = (int)info.height;
    img->state = ST_READY;
    pixels_used += count;
    return img;
}

/* Area average (shrinking) or bilinear (enlarging) resampling of
 * premultiplied pixels. */
static void resample(const uint32_t* src, int sw, int sh, uint32_t* dst, int dw, int dh) {
    if (dw <= sw && dh <= sh) {
        for (int y = 0; y < dh; y++) {
            int y0 = (int)((int64_t)y * sh / dh), y1 = (int)((int64_t)(y + 1) * sh / dh);
            if (y1 <= y0) y1 = y0 + 1;
            for (int x = 0; x < dw; x++) {
                int x0 = (int)((int64_t)x * sw / dw), x1 = (int)((int64_t)(x + 1) * sw / dw);
                if (x1 <= x0) x1 = x0 + 1;
                uint32_t a = 0, r = 0, g = 0, b = 0, n = 0;
                for (int yy = y0; yy < y1; yy++) {
                    const uint32_t* row = src + (size_t)yy * sw;
                    for (int xx = x0; xx < x1; xx++) {
                        uint32_t c = row[xx];
                        a += c >> 24; r += (c >> 16) & 255u; g += (c >> 8) & 255u; b += c & 255u;
                        n++;
                    }
                }
                dst[(size_t)y * dw + x] = (a / n) << 24 | (r / n) << 16 | (g / n) << 8 | (b / n);
            }
        }
        return;
    }
    for (int y = 0; y < dh; y++) {
        /* source position in 1/256 pixels, pixel centres aligned */
        int fy = (int)(((int64_t)(2 * y + 1) * sh * 128) / dh) - 128;
        if (fy < 0) fy = 0;
        int y0 = fy >> 8, ty = fy & 255;
        int y1 = y0 + 1 < sh ? y0 + 1 : sh - 1;
        if (y0 >= sh) y0 = y1 = sh - 1;
        for (int x = 0; x < dw; x++) {
            int fx = (int)(((int64_t)(2 * x + 1) * sw * 128) / dw) - 128;
            if (fx < 0) fx = 0;
            int x0 = fx >> 8, tx = fx & 255;
            int x1 = x0 + 1 < sw ? x0 + 1 : sw - 1;
            if (x0 >= sw) x0 = x1 = sw - 1;
            uint32_t c00 = src[(size_t)y0 * sw + x0], c01 = src[(size_t)y0 * sw + x1];
            uint32_t c10 = src[(size_t)y1 * sw + x0], c11 = src[(size_t)y1 * sw + x1];
            uint32_t out = 0;
            for (int s = 0; s < 32; s += 8) {
                uint32_t top = ((c00 >> s) & 255u) * (256u - tx) + ((c01 >> s) & 255u) * (uint32_t)tx;
                uint32_t bot = ((c10 >> s) & 255u) * (256u - tx) + ((c11 >> s) & 255u) * (uint32_t)tx;
                uint32_t v = (top * (256u - ty) + bot * (uint32_t)ty) >> 16;
                out |= (v > 255u ? 255u : v) << s;
            }
            dst[(size_t)y * dw + x] = out;
        }
    }
}

/* Blends premultiplied `src` (stride sw, drawn at x, y) into the canvas. */
static void blit(const mx_canvas_t* c, const uint32_t* src, int sw, int w, int h, int x, int y,
                 unsigned opacity) {
    int x0 = x > c->clip_x0 ? x : c->clip_x0, y0 = y > c->clip_y0 ? y : c->clip_y0;
    int x1 = x + w < c->clip_x1 ? x + w : c->clip_x1, y1 = y + h < c->clip_y1 ? y + h : c->clip_y1;
    for (int py = y0; py < y1; py++) {
        const uint32_t* s = src + (size_t)(py - y) * sw + (x0 - x);
        uint32_t* d = c->pixels + (size_t)py * c->width + x0;
        for (int px = x0; px < x1; px++, s++, d++) {
            uint32_t v = *s;
            if (opacity < 255) {
                uint32_t rb = ((v & 0x00FF00FFu) * opacity >> 8) & 0x00FF00FFu;
                uint32_t ag = (((v >> 8) & 0x00FF00FFu) * opacity >> 8) & 0x00FF00FFu;
                v = ag << 8 | rb;
            }
            uint32_t a = v >> 24;
            if (a == 255) { *d = v; continue; }
            if (!a) continue;
            uint32_t k = 255u - a, o = *d;
            uint32_t rb = ((o & 0x00FF00FFu) * k / 255u) & 0x00FF00FFu;
            uint32_t g = ((o & 0x0000FF00u) * k / 255u) & 0x0000FF00u;
            *d = 0xFF000000u | ((rb + (v & 0x00FF00FFu)) & 0x00FF00FFu) |
                 ((g + (v & 0x0000FF00u)) & 0x0000FF00u);
        }
    }
}

static void draw_image(const mx_canvas_t* c, image_t* img, int x, int y, int w, int h,
                       unsigned opacity) {
    if (w <= 0 || h <= 0 || img->state != ST_READY) return;
    if (w == img->w && h == img->h) {
        blit(c, img->px, img->w, w, h, x, y, opacity);
        return;
    }
    if (img->sw != w || img->sh != h) {
        free(img->scaled);
        img->scaled = NULL;
        img->sw = img->sh = 0;
        if ((size_t)w * h <= 16u * 1024u * 1024u)
            img->scaled = (uint32_t*)malloc((size_t)w * h * 4u);
        if (!img->scaled) return;
        resample(img->px, img->w, img->h, img->scaled, w, h);
        img->sw = w;
        img->sh = h;
    }
    blit(c, img->scaled, w, w, h, x, y, opacity);
}

/* ====================================================================== */
/* Videos                                                                 */
/* ====================================================================== */

static bool read_memory(void* ctx, uint64_t offset, void* buf, size_t len) {
    player_t* p = (player_t*)ctx;
    if (offset > p->size || len > p->size - offset) return false;
    memcpy(buf, p->data + offset, len);
    return true;
}

#ifndef MX_HOST
static bool read_fd(void* ctx, uint64_t offset, void* buf, size_t len) {
    player_t* p = (player_t*)ctx;
    if (offset > 0x7FFFFFFFull || mos_seek(p->fd, (long)offset) < 0) return false;
    uint8_t* d = (uint8_t*)buf;
    while (len) {
        long got = mos_read(p->fd, d, len);
        if (got <= 0) return false;
        d += got;
        len -= (size_t)got;
    }
    return true;
}
#endif

static void* media_alloc(size_t n) { return malloc(n); }
static void media_free(void* p) { free(p); }

static int open_player(player_t* p) {
    char path[256];
    p->fd = -1;
    if (mx_url_local_path(p->url, path, sizeof(path))) {
        if (!allow_local) {
            mx_console_add(MX_LOG_WARN, "Media", 0,
                           "Pages from the network cannot show local files.");
            return 0;
        }
        mx_network_entry_t* e = mx_network_add(p->url, "video");
        mx_copy(e->content_type, sizeof(e->content_type), "local file");
#ifdef MX_HOST
        p->data = read_local(path, (size_t)1 << 31, &p->size);
        e->status = p->data ? 200 : 0;
        e->size = p->size;
        if (!p->data) return 0;
        return mvid_open(&p->r, read_memory, p, p->size, media_alloc);
#else
        /* local videos are read as they play */
        p->fd = mos_open(path, SYS_O_RDONLY);
        long size = p->fd >= 0 ? mos_size(p->fd) : -1;
        e->status = size > 0 ? 200 : 0;
        e->size = size > 0 ? (size_t)size : 0;
        if (size <= 0) return 0;
        mx_copy(p->path, sizeof(p->path), path);
        return mvid_open(&p->r, read_fd, p, (uint64_t)size, media_alloc);
#endif
    }
    p->data = load_file(p->url, "video", MX_HTTP_MEDIA_MAX, &p->size);
    if (!p->data) return 0;
    return mvid_open(&p->r, read_memory, p, p->size, media_alloc);
}

#ifndef MX_HOST
static int owns_sound(player_t* p, syscall_audio_status_t* st);
#endif

static void close_player(player_t* p) {
#ifndef MX_HOST
    syscall_audio_status_t st;
    if (p->sound && owns_sound(p, &st)) mos_audio_stop();   /* not another program's */
    if (p->fd >= 0) mos_close(p->fd);
#endif
    p->sound = 0;
    if (p->state == ST_READY) mvid_close(&p->r, media_free);
    free(p->frame);
    free(p->data);
    memset(p, 0, sizeof(*p));
    p->fd = -1;
}

static player_t* find_player(mx_node_t* n) {
    for (int i = 0; i < player_count; i++)
        if (players[i].node == n) return &players[i];
    return NULL;
}

/* The video's address: src="" or the first <source> naming a .vid. */
static int video_url(mx_node_t* n, char* out, size_t capacity) {
    const char* src = mx_dom_attr(n, "src");
    if (src && *src) {
        mx_html_resolve(src, out, capacity);
        return mx_media_kind_of_url(out) == MX_MEDIA_VIDEO;
    }
    for (mx_node_t* c = n->first; c; c = c->next) {
        if (!mx_dom_is(c, "source")) continue;
        src = mx_dom_attr(c, "src");
        if (!src || !*src) continue;
        mx_html_resolve(src, out, capacity);
        if (mx_media_kind_of_url(out) == MX_MEDIA_VIDEO) return 1;
    }
    return 0;
}

static player_t* get_player(mx_node_t* n) {
    char url[URL_MAX];
    if (!video_url(n, url, sizeof(url))) {
        player_t* old = find_player(n);
        if (old) close_player(old);   /* the source went away */
        return NULL;
    }
    player_t* p = find_player(n);
    if (p && !strcmp(p->url, url)) return p;
    if (p) {
        close_player(p);   /* the source changed */
    } else {
        for (int i = 0; i < player_count && !p; i++)
            if (!players[i].node) p = &players[i];
        if (!p) {
            if (player_count >= MAX_PLAYERS) return NULL;
            p = &players[player_count++];
        }
        memset(p, 0, sizeof(*p));
    }
    p->node = n;
    mx_copy(p->url, sizeof(p->url), url);
    p->state = ST_FAILED;
    p->shown = -1;
    p->muted = mx_dom_attr(n, "muted") != NULL;
    if (!open_player(p)) {
        report("Could not load the video (.vid)", url);
        return p;
    }
    p->state = ST_READY;
    p->frame = (uint32_t*)calloc((size_t)p->r.info.width * p->r.info.height, 4u);
    if (!p->frame) {
        report("Not enough memory for the video", url);
        mvid_close(&p->r, media_free);
        p->state = ST_FAILED;
        return p;
    }
    if (mvid_decode(&p->r, 0, p->frame)) p->shown = 0;
    return p;
}

static uint32_t duration_of(const player_t* p) { return p->r.info.duration_ms; }

#ifndef MX_HOST
/* The kernel's sound is this video's (nobody else took it). */
static int owns_sound(player_t* p, syscall_audio_status_t* st) {
    mos_audio_status(st);
    return st->state != SYSCALL_AUDIO_IDLE && !strcmp(st->path, p->path);
}

/* A file the kernel can play the soundtrack from. */
static int sound_path(player_t* p) {
    if (p->fd >= 0) return p->path[0] != '\0';
    if (!strcmp(sound_file_url, p->url)) {
        mx_copy(p->path, sizeof(p->path), SOUND_FILE);
        return 1;
    }
    if (!mos_exists("0:/data") && mos_mkdir("0:/data") != SYS_SUCCESS) return 0;
    if (mos_exists(SOUND_FILE)) mos_syscall(SYS_DELETE, (long)(uintptr_t)SOUND_FILE, 0, 0);
    sound_file_url[0] = '\0';
    if (mos_create(SOUND_FILE, "video", "vid") < 0) return 0;
    long fd = mos_open(SOUND_FILE, SYS_O_RDWR);
    if (fd < 0) return 0;
    long written = mos_fwrite(fd, p->data, p->size);
    mos_close(fd);
    if (written != (long)p->size) return 0;
    mx_copy(sound_file_url, sizeof(sound_file_url), p->url);
    mx_copy(p->path, sizeof(p->path), SOUND_FILE);
    return 1;
}
#endif

static void start_sound(player_t* p, uint32_t ms) {
#ifdef MX_HOST
    (void)p;
    (void)ms;
#else
    p->sound = 0;
    if (p->muted || !p->r.info.has_audio) return;
    for (int i = 0; i < player_count; i++) players[i].sound = 0;   /* one sound at a time */
    if (!sound_path(p)) return;
    if (mos_audio_open_at(p->path, (uint32_t)p->r.info.audio_offset) != (long)SYS_SUCCESS) return;
    mos_audio_seek(ms);
    mos_audio_resume();
    p->sound = 1;
#endif
}

static void start_at(player_t* p, uint32_t ms) {
    if (ms >= duration_of(p)) ms = 0;
    long now = mx_now_ms();
    p->pos_ms = ms;
    p->playing = 1;
    p->ended = 0;
    p->started = 1;
    p->clock_start = now - (long)ms;
    p->audio_pos = ms;
    p->audio_seen = now;
    start_sound(p, ms);
}

static void pause_sound(player_t* p) {
#ifdef MX_HOST
    (void)p;
#else
    syscall_audio_status_t st;
    if (p->sound && owns_sound(p, &st)) mos_audio_pause();
#endif
}

/* The position now, in milliseconds. */
static uint32_t position(player_t* p) {
    if (!p->playing) return p->pos_ms;
    long now = mx_now_ms();
    uint32_t pos = (uint32_t)(now - p->clock_start);
#ifndef MX_HOST
    if (p->sound) {
        syscall_audio_status_t st;
        if (!owns_sound(p, &st)) {
            p->sound = 0;   /* another program took the sound: keep our own time */
        } else if (st.state == SYSCALL_AUDIO_ENDED) {
            pos = duration_of(p);
        } else {
            /* the kernel reports in steps; fill in between them */
            if (st.position_ms != p->audio_pos) { p->audio_pos = st.position_ms; p->audio_seen = now; }
            long since = now - p->audio_seen;
            pos = p->audio_pos + (uint32_t)(since < 500 ? since : 500);
            p->clock_start = now - (long)pos;
        }
    }
#endif
    if (pos >= duration_of(p)) {
        if (p->node && mx_dom_attr(p->node, "loop")) {
            start_at(p, 0);
            return 0;
        }
        pos = duration_of(p);
        p->playing = 0;
        p->ended = 1;
        pause_sound(p);
    }
    p->pos_ms = pos;
    return pos;
}

static void pause_player(player_t* p) {
    if (p->playing) {
        p->pos_ms = position(p);   /* may end the video */
        p->playing = 0;
    }
    pause_sound(p);
}

static void seek_player(player_t* p, uint32_t ms) {
    if (ms > duration_of(p)) ms = duration_of(p);
    p->ended = 0;
    if (p->playing) {
        start_at(p, ms);
    } else {
        p->pos_ms = ms;
#ifndef MX_HOST
        syscall_audio_status_t st;
        if (p->sound && owns_sound(p, &st)) mos_audio_seek(ms);
#endif
    }
}

/* Decodes the frame for the current time; 1 when it changed. */
static int update_frame(player_t* p) {
    if (p->state != ST_READY || !p->frame) return 0;
    uint32_t n = mvid_frame_at(&p->r.info, position(p));
    if ((int64_t)n == p->shown) return 0;
    if (!mvid_decode(&p->r, n, p->frame)) {
        report("Damaged frame in the video", p->url);
        pause_player(p);
        return 0;
    }
    p->shown = n;
    return 1;
}

static void format_time(char* out, size_t capacity, uint32_t ms) {
    uint32_t s = ms / 1000u;
    out[0] = '\0';
    mx_append_int(out, capacity, (int)(s / 60u));
    mx_append(out, capacity, s % 60u < 10u ? ":0" : ":");
    mx_append_int(out, capacity, (int)(s % 60u));
}

/* Fits sw x sh inside the box, keeping the shape. */
static void contain(int sw, int sh, int x, int y, int w, int h, int* ox, int* oy, int* ow, int* oh) {
    int fw = w, fh = sw ? (int)((int64_t)sh * w / sw) : h;
    if (fh > h) { fh = h; fw = sh ? (int)((int64_t)sw * h / sh) : w; }
    *ow = fw; *oh = fh;
    *ox = x + (w - fw) / 2;
    *oy = y + (h - fh) / 2;
}

static void draw_frame(const mx_canvas_t* c, const player_t* p, int x, int y, int w, int h,
                       unsigned opacity) {
    int vw = (int)p->r.info.width, vh = (int)p->r.info.height;
    if (w <= 0 || h <= 0 || p->shown < 0) return;
    if (xmap_cap < w) {
        free(xmap);
        xmap = (uint32_t*)malloc((size_t)w * 4u);
        xmap_cap = xmap ? w : 0;
        if (!xmap) return;
    }
    for (int i = 0; i < w; i++) xmap[i] = (uint32_t)((int64_t)i * vw / w);
    int x0 = x > c->clip_x0 ? x : c->clip_x0, y0 = y > c->clip_y0 ? y : c->clip_y0;
    int x1 = x + w < c->clip_x1 ? x + w : c->clip_x1, y1 = y + h < c->clip_y1 ? y + h : c->clip_y1;
    for (int py = y0; py < y1; py++) {
        const uint32_t* src = p->frame + (size_t)((int64_t)(py - y) * vh / h) * vw;
        uint32_t* d = c->pixels + (size_t)py * c->width;
        for (int px = x0; px < x1; px++) {
            uint32_t s = src[xmap[px - x]];
            uint32_t a = (s >> 24) * opacity / 255u;
            if (a == 255) { d[px] = s | 0xFF000000u; continue; }
            d[px] = mx_mix(d[px], s | 0xFF000000u, a);
        }
    }
}

static int has_controls(mx_node_t* n) { return mx_dom_attr(n, "controls") != NULL; }

/* The control bar: the seek line runs from *t0 to *t1; the time text
 * (*tw wide, 0 when there is no room for it) sits at the right. */
static void bar_layout(const player_t* p, int x, int w, int* t0, int* t1, int* tw) {
    char a[16], text[40];
    format_time(a, sizeof(a), duration_of(p));
    mx_copy(text, sizeof(text), a);
    mx_append(text, sizeof(text), " / ");
    mx_append(text, sizeof(text), a);
    *tw = mx_text_width_px(text, (size_t)-1, 12, 0) + 6;
    *t0 = x + 38;
    *t1 = x + w - *tw - 22;
    if (*t1 - *t0 < 48) {
        *tw = 0;
        *t1 = x + w - 14;
    }
}

static void draw_controls(const mx_canvas_t* c, player_t* p, int x, int y, int w, int h,
                          uint32_t accent) {
    int big = !p->started || p->ended;
    if (big && w >= 72 && h >= BAR_H * 2 + 64) {
        int cx = x + w / 2, cy = y + h / 2;
        mx_circle(c, cx, cy, 30, 0xB0000000u);
        /* a triangle pointing right, one column at a time */
        for (int i = 0; i < 22; i++) {
            int half = 12 - i * 12 / 22;
            mx_fill(c, cx - 8 + i, cy - half, 1, 2 * half, 0xFFFFFFFFu);
        }
    }
    if (h < BAR_H + 8 || w < 120) return;
    int by = y + h - BAR_H;
    mx_fill(c, x, by, w, BAR_H, 0x99000000u);
    mx_icon(c, p->playing ? MX_ICON_PAUSE : MX_ICON_PLAY_ARROW, 20, x + 8, by + (BAR_H - 20) / 2,
            0xFFFFFFFFu);
    char now[16], total[16], text[40];
    uint32_t pos = p->playing ? position(p) : p->pos_ms;
    int t0, t1, tw, ly = by + BAR_H / 2;
    bar_layout(p, x, w, &t0, &t1, &tw);
    if (tw) {
        format_time(now, sizeof(now), pos);
        format_time(total, sizeof(total), duration_of(p));
        mx_copy(text, sizeof(text), now);
        mx_append(text, sizeof(text), " / ");
        mx_append(text, sizeof(text), total);
        int ty = by + (BAR_H - mx_text_height_px(12, 0)) / 2;
        mx_text(c, x + w - tw - 10, ty, text, strlen(text), 0xFFF2F5F8u, 12, 0);
    }
    if (t1 - t0 < 8) return;
    int at = duration_of(p) ? t0 + (int)((int64_t)(t1 - t0) * pos / duration_of(p)) : t0;
    mx_round_rect(c, t0, ly - 2, t1 - t0, 4, 2, 0x66FFFFFFu);
    if (at > t0) mx_round_rect(c, t0, ly - 2, at - t0, 4, 2, accent | 0xFF000000u);
    mx_circle(c, at, ly, 6, 0xFFFFFFFFu);
}

/* ====================================================================== */
/* Public API                                                             */
/* ====================================================================== */

void mx_media_begin(mx_fetch_fn fetch, void* user, int local) {
    mx_media_end();
    fetch_fn = fetch;
    fetch_user = user;
    allow_local = local;
}

void mx_media_end(void) {
    for (int i = 0; i < image_count; i++) {
        free(images[i].px);
        free(images[i].scaled);
    }
    image_count = 0;
    pixels_used = 0;
    for (int i = 0; i < player_count; i++) close_player(&players[i]);
    player_count = 0;
    fetch_fn = NULL;
    fetch_user = NULL;
    allow_local = 0;
}

static image_t* element_image(mx_node_t* n, const char* attr) {
    const char* src = mx_dom_attr(n, attr);
    if (!src || !*src) return NULL;
    char url[URL_MAX];
    mx_html_resolve(src, url, sizeof(url));
    if (mx_media_kind_of_url(url) != MX_MEDIA_IMAGE) return NULL;
    return get_image(url);
}

int mx_media_natural_size(mx_node_t* n, int* w, int* h) {
    if (!n || n->type != MX_NODE_ELEMENT) return 0;
    if (mx_dom_is(n, "img")) {
        image_t* img = element_image(n, "src");
        if (!img || img->state != ST_READY) return 0;
        *w = img->w;
        *h = img->h;
        return 1;
    }
    if (mx_dom_is(n, "video")) {
        player_t* p = get_player(n);
        if (p && p->state == ST_READY) {
            *w = (int)p->r.info.width;
            *h = (int)p->r.info.height;
            return 1;
        }
        image_t* poster = element_image(n, "poster");
        if (poster && poster->state == ST_READY) {
            *w = poster->w;
            *h = poster->h;
            return 1;
        }
    }
    return 0;
}

int mx_media_failed(mx_node_t* n) {
    if (!n || !mx_dom_is(n, "img")) return 0;
    const char* src = mx_dom_attr(n, "src");
    if (!src || !*src) return 0;
    char url[URL_MAX];
    mx_html_resolve(src, url, sizeof(url));
    image_t* img = find_image(url);
    return img && img->state == ST_FAILED;
}

void mx_media_paint(const mx_canvas_t* c, mx_node_t* n, int x, int y, int w, int h,
                    unsigned opacity, uint32_t accent) {
    if (mx_dom_is(n, "img")) {
        image_t* img = element_image(n, "src");
        if (img) draw_image(c, img, x, y, w, h, opacity);
        return;
    }
    if (!mx_dom_is(n, "video")) return;
    mx_fill(c, x, y, w, h, mx_with_alpha(0xFF000000u, opacity));
    player_t* p = get_player(n);
    image_t* poster = element_image(n, "poster");
    int ox, oy, ow, oh;
    if (poster && poster->state == ST_READY && (!p || !p->started)) {
        contain(poster->w, poster->h, x, y, w, h, &ox, &oy, &ow, &oh);
        draw_image(c, poster, ox, oy, ow, oh, opacity);
    } else if (p && p->state == ST_READY) {
        contain((int)p->r.info.width, (int)p->r.info.height, x, y, w, h, &ox, &oy, &ow, &oh);
        draw_frame(c, p, ox, oy, ow, oh, opacity);
    }
    if (!p || p->state != ST_READY) {
        if (w >= 24 && h >= 24)
            mx_icon(c, MX_ICON_BROKEN_IMAGE, w >= 60 && h >= 60 ? 48 : 16,
                    x + (w - (w >= 60 && h >= 60 ? 48 : 16)) / 2,
                    y + (h - (w >= 60 && h >= 60 ? 48 : 16)) / 2, 0x99FFFFFFu);
        return;
    }
    if (has_controls(n)) draw_controls(c, p, x, y, w, h, accent);
}

int mx_media_click(mx_node_t* n, int x, int y, int bx, int by, int bw, int bh) {
    if (!n || !mx_dom_is(n, "video") || !has_controls(n)) return 0;
    player_t* p = get_player(n);
    if (!p || p->state != ST_READY) return 0;
    if (y >= by + bh - BAR_H && bh >= BAR_H + 8 && bw >= 120) {
        int t0, t1, tw;
        bar_layout(p, bx, bw, &t0, &t1, &tw);
        if (x >= t0 - 6 && x <= t1 + 6 && t1 > t0) {
            int at = x < t0 ? 0 : x > t1 ? t1 - t0 : x - t0;
            seek_player(p, (uint32_t)((int64_t)duration_of(p) * at / (t1 - t0)));
            update_frame(p);
            return 1;
        }
        if (x >= bx + 38) return 1;   /* the time: nothing to do */
    }
    if (p->playing) pause_player(p);
    else start_at(p, p->ended ? 0 : p->pos_ms);
    return 1;
}

int mx_media_pointer(mx_node_t* n) {
    return n && mx_dom_is(n, "video") && has_controls(n);
}

int mx_media_tick(long now_ms) {
    (void)now_ms;
    int dirty = 0;
    for (int i = 0; i < player_count; i++) {
        player_t* p = &players[i];
        if (!p->node || p->state != ST_READY) continue;
        if (!p->autoplay_done) {
            p->autoplay_done = 1;
            if (mx_dom_attr(p->node, "autoplay")) {
                start_at(p, 0);
                dirty = 1;
            }
        }
        if (!p->playing) continue;
        if (update_frame(p)) dirty = 1;
        uint32_t second = p->pos_ms / 1000u;
        if (second != p->last_second || !p->playing) {
            p->last_second = second;
            dirty = 1;   /* the time in the controls, or it just ended */
        }
    }
    return dirty;
}

int mx_media_playing(void) {
    for (int i = 0; i < player_count; i++)
        if (players[i].node && players[i].playing) return 1;
    return 0;
}

static player_t* ready_player(mx_node_t* n) {
    if (!n || !mx_dom_is(n, "video")) return NULL;
    player_t* p = get_player(n);
    return p && p->state == ST_READY ? p : NULL;
}

void mx_media_play(mx_node_t* n) {
    player_t* p = ready_player(n);
    if (p && !p->playing) start_at(p, p->ended ? 0 : p->pos_ms);
}

void mx_media_pause(mx_node_t* n) {
    player_t* p = ready_player(n);
    if (p) pause_player(p);
}

int mx_media_paused(mx_node_t* n) {
    player_t* p = ready_player(n);
    return !p || !p->playing;
}

int mx_media_ended(mx_node_t* n) {
    player_t* p = ready_player(n);
    return p && p->ended;
}

double mx_media_current_time(mx_node_t* n) {
    player_t* p = ready_player(n);
    return p ? position(p) / 1000.0 : 0.0;
}

void mx_media_seek(mx_node_t* n, double seconds) {
    player_t* p = ready_player(n);
    if (!p) return;
    if (seconds < 0) seconds = 0;
    seek_player(p, (uint32_t)(seconds * 1000.0));
    update_frame(p);
}

double mx_media_duration(mx_node_t* n) {
    player_t* p = ready_player(n);
    return p ? duration_of(p) / 1000.0 : 0.0;
}

void mx_media_set_muted(mx_node_t* n, int muted) {
    player_t* p = ready_player(n);
    if (!p || p->muted == !!muted) return;
    p->muted = !!muted;
    if (!p->playing) return;
    uint32_t pos = position(p);
    if (p->muted) {
#ifndef MX_HOST
        syscall_audio_status_t st;
        if (p->sound && owns_sound(p, &st)) mos_audio_stop();
#endif
        p->sound = 0;
        p->clock_start = mx_now_ms() - (long)pos;
    } else {
        start_at(p, pos);
    }
}

int mx_media_muted(mx_node_t* n) {
    player_t* p = ready_player(n);
    return p ? p->muted : mx_dom_attr(n, "muted") != NULL;
}

